import { booleanAttribute, ChangeDetectionStrategy, Component, input, output } from '@angular/core';
import { ButtonDirective } from './button';
import { IconComponent } from './icon';

/**
 * An AI-generated example, written as unconfirmed ("Generated by AI, review needed") until a person acts.
 * The buttons are named "Accept <name>", "Edit <name>" and "Reject <name>".
 */
@Component({
  selector: 'mk-ai-ghost-row',
  changeDetection: ChangeDetectionStrategy.OnPush,
  imports: [ButtonDirective, IconComponent],
  host: {
    class: 'di-ai-row',
    role: 'group',
    '[attr.aria-label]': "'AI suggestion: ' + name()",
    '[attr.aria-busy]': "busy() ? 'true' : null",
  },
  template: `
    <span class="di-ai-row-label"><svg mkIcon name="spark" [size]="14"></svg>Generated by AI, review needed</span>
    <span class="di-ai-row-body"><ng-content /></span>
    <span class="di-ai-row-actions">
      <button type="button" mkButton variant="primary" size="sm" [disabled]="busy()" (click)="accept.emit()">Accept <span class="di-sr-only">{{ name() }}</span></button>
      <button type="button" mkButton variant="secondary" size="sm" [disabled]="busy()" (click)="edit.emit()">Edit <span class="di-sr-only">{{ name() }}</span></button>
      <button type="button" mkButton variant="ghost" size="sm" [disabled]="busy()" (click)="reject.emit()">Reject <span class="di-sr-only">{{ name() }}</span></button>
    </span>
  `,
})
export class AiGhostRowComponent {
  /** Name of the suggestion. It completes the button names ("Accept <name>"). */
  readonly name = input.required<string>();
  readonly busy = input(false, { transform: booleanAttribute });
  readonly accept = output<void>();
  readonly edit = output<void>();
  readonly reject = output<void>();
}
